  const nav = (route) => {
    const spaceAliases = {'space-plan':'space-questions','space-knowledge':'space-materials','space-data':'space-materials','space-assets':'space-materials','space-conclusions':'space-questions','space-collab':'space-tasks','space-activity':'space-overview'};
    route = spaceAliases[route] || route;
    if(route==='space-overview'&&['全部科研活动','个人探索'].includes(state.scope)){let recent=initialSpace;try{recent=localStorage.getItem(recentSpaceKey)||initialSpace;}catch{} state.scope=topSpaceOptions.some(x=>x[0]===recent&&x[2])?recent:initialSpace;state.currentSpace=state.scope;}
    if(route.startsWith('space-')&&!['全部科研活动','个人探索'].includes(state.scope)){state.currentSpace=state.scope;rememberSpace(state.scope);}
    if (route === 'resources') route = 'resource-knowledge';
    if (route === 'hub' && state.route.startsWith('space-')) { state.scope=state.currentSpace; state.deskPrompt=document.querySelector('.space-ai-input input')?.value?.trim() || spaceProblem().question; state.hubSession=false; }
    if (['cockpit','workbench','hub','spaces'].includes(route) || isResourceRoute(route) || route.startsWith('space-')) state.authenticated = true;
    if (route.startsWith('resource-')) { state.catalogRelation='全部资源';state.catalogToolView='全部';state.catalogDomain='全部领域'; state.catalogFacet='全部'; state.catalogDirection='全部方向'; state.catalogQuery=''; state.catalogVisible=18; state.catalogKnowledgeView='统一检索'; }
    state.route = route;
    if (isResourceRoute(route) && state.route.startsWith('space-')) state.resourceReturnRoute=state.route;
    overlayRoot.innerHTML = '';
    render();
    const main = document.querySelector('.main-canvas, .hub-thread');
    if (main) main.scrollTop = 0;
  };

  const toast = (title, description) => {
    const root = document.getElementById('toast-root');
    const node = document.createElement('div');
    node.className = 'toast';
    node.innerHTML = `<strong>${title}</strong><span>${description}</span>`;
    root.appendChild(node);
    setTimeout(() => node.remove(), 2600);
  };

  const openDrawer = (kind) => {
    const content = kind === 'scope' ? scopeDrawer() : copilotDrawer();
    overlayRoot.innerHTML = `<div class="overlay" data-close-overlay><section class="drawer" role="dialog" aria-modal="true">${content}</section></div>`;
    overlayRoot.querySelector('[data-close-overlay]').addEventListener('mousedown', (event) => {
      if (event.target.hasAttribute('data-close-overlay')) overlayRoot.innerHTML = '';
    });
    overlayRoot.querySelectorAll('[data-action]').forEach((el) => el.addEventListener('click', () => handleAction(el.dataset.action)));
    overlayRoot.querySelectorAll('[data-scope]').forEach((el) => el.addEventListener('click', () => {
      state.scope = el.dataset.scope;
      if (!['全部科研活动','个人探索'].includes(state.scope)) state.currentSpace = state.scope;
      closeOverlay();
      render();
      toast('工作范围已切换', `当前上下文：${state.scope}`);
    }));
  };

  const closeOverlay = () => { overlayRoot.innerHTML = ''; };

