    deskListen('[data-toggle-schedule]',el=>{ const title=el.dataset.toggleSchedule; const enabled=state.pausedSchedules.includes(title); state.pausedSchedules=enabled?state.pausedSchedules.filter(x=>x!==title):[...state.pausedSchedules,title]; render(); toast(enabled?'定时计划已启用':'定时计划已暂停','已有执行记录保留；原型不会触发真实后台执行'); });
