    document.querySelectorAll('[data-route]').forEach((el) => el.addEventListener('click', () => nav(el.dataset.route)));
    document.querySelectorAll('[data-portal-anchor]').forEach((el) => el.addEventListener('click', () => setTimeout(() => document.getElementById(el.dataset.portalAnchor)?.scrollIntoView({behavior:'smooth'}), 0)));
    document.querySelectorAll('[data-action]').forEach((el) => { if(el.dataset.actionBound) return; el.dataset.actionBound='true'; el.addEventListener('click', () => { if (['accept-ai-task','schedule-ai-task'].includes(el.dataset.action)) { const recommendation=el.closest('.ai-recommend-item'); if(recommendation){state.proposedTask=recommendation.dataset.recommendTitle; state.proposedScope=recommendation.dataset.recommendScope;} else if(!el.closest('.research-detail-drawer')) {state.proposedTask='新的定时研究任务'; state.proposedScope='个人探索';} } handleAction(el.dataset.action); }); });
    document.querySelectorAll('[data-filter]').forEach((el) => el.addEventListener('click', () => { state.resourceFilter = el.dataset.filter; render(); }));
