    document.querySelectorAll('[data-public-facet]').forEach((el) => el.addEventListener('click', () => { const values = el.dataset.facetOptions.split('|'); const current = state.publicFacetSelections[el.dataset.publicFacet] || '全部'; state.publicFacetSelections[el.dataset.publicFacet] = values[(values.indexOf(current) + 1) % values.length]; render(); }));
