    document.querySelectorAll('[data-scope]').forEach((el) => el.addEventListener('click', () => { state.scope = el.dataset.scope; if (!['全部科研活动','个人探索'].includes(state.scope)) state.currentSpace = state.scope; closeOverlay(); render(); toast('工作范围已切换', `当前上下文：${state.scope}`); }));
