    if(drawer&&!drawer.dataset.focusBound){drawer.dataset.focusBound='true';drawer.addEventListener('keydown',event=>{if(event.key!=='Tab')return;const controls=[...drawer.querySelectorAll('button,input,select,textarea,a[href]')].filter(e=>!e.hidden&&e.offsetParent!==null);const first=controls[0],last=controls.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}});}
