    if(action==='session-collaboration'||action==='mention-collaborator') return collaborationDrawer(action==='mention-collaborator');
    if(action==='associate-collaboration-space') {const scope=document.getElementById('collab-space')?.value;if(!scope)return;state.scope=scope;state.currentSpace=scope;closeOverlay();render();collaborationDrawer();return;}
    if(action==='invite-session-member') {const name=document.getElementById('collab-member')?.value,role=document.getElementById('collab-role')?.value,record=collaborationRecord();if(!name)return;if(!record.invites.some(x=>x.name===name))record.invites.push({name,role});collaborationDrawer();toast('协同邀请已记录（演示）','成员接受后可参与；原材料权限保持不变');return;}
